//! Line/word diff engine (Myers linear-space algorithm with replace grouping
//! and inline word-level refinement).

use std::ops::Range;
use std::time::{Duration, Instant};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DiffOp {
    Equal { old_index: usize, new_index: usize, len: usize },
    Delete { old_index: usize, old_len: usize, new_index: usize },
    Insert { old_index: usize, new_index: usize, new_len: usize },
    Replace { old_index: usize, old_len: usize, new_index: usize, new_len: usize },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Tag {
    Equal,
    Delete,
    Insert,
    Replace,
}

impl DiffOp {
    pub fn tag(&self) -> Tag {
        match self {
            DiffOp::Equal { .. } => Tag::Equal,
            DiffOp::Delete { .. } => Tag::Delete,
            DiffOp::Insert { .. } => Tag::Insert,
            DiffOp::Replace { .. } => Tag::Replace,
        }
    }
    pub fn old_range(&self) -> Range<usize> {
        match *self {
            DiffOp::Equal { old_index, len, .. } => old_index..old_index + len,
            DiffOp::Delete { old_index, old_len, .. } => old_index..old_index + old_len,
            DiffOp::Insert { old_index, .. } => old_index..old_index,
            DiffOp::Replace { old_index, old_len, .. } => old_index..old_index + old_len,
        }
    }
    pub fn new_range(&self) -> Range<usize> {
        match *self {
            DiffOp::Equal { new_index, len, .. } => new_index..new_index + len,
            DiffOp::Delete { new_index, .. } => new_index..new_index,
            DiffOp::Insert { new_index, new_len, .. } => new_index..new_index + new_len,
            DiffOp::Replace { new_index, new_len, .. } => new_index..new_index + new_len,
        }
    }
}

/// Collects raw hook calls and merges them into grouped ops (replace hook).
struct Replace {
    ops: Vec<DiffOp>,
    del: Option<(usize, usize, usize)>,
    ins: Option<(usize, usize, usize)>,
    eq: Option<(usize, usize, usize)>,
}

impl Replace {
    fn new() -> Self {
        Replace { ops: vec![], del: None, ins: None, eq: None }
    }
    fn flush_eq(&mut self) {
        if let Some((old_index, new_index, len)) = self.eq.take() {
            self.ops.push(DiffOp::Equal { old_index, new_index, len });
        }
    }
    fn flush_del_ins(&mut self) {
        if let Some((del_old_index, del_old_len, del_new_index)) = self.del.take() {
            if let Some((_, ins_new_index, ins_new_len)) = self.ins.take() {
                self.ops.push(DiffOp::Replace {
                    old_index: del_old_index,
                    old_len: del_old_len,
                    new_index: ins_new_index,
                    new_len: ins_new_len,
                });
            } else {
                self.ops.push(DiffOp::Delete {
                    old_index: del_old_index,
                    old_len: del_old_len,
                    new_index: del_new_index,
                });
            }
        } else if let Some((ins_old_index, ins_new_index, ins_new_len)) = self.ins.take() {
            self.ops.push(DiffOp::Insert {
                old_index: ins_old_index,
                new_index: ins_new_index,
                new_len: ins_new_len,
            });
        }
    }
    fn equal(&mut self, old_index: usize, new_index: usize, len: usize) {
        self.flush_del_ins();
        self.eq = Some(match self.eq {
            Some((a, b, c)) => (a, b, c + len),
            None => (old_index, new_index, len),
        });
    }
    fn delete(&mut self, old_index: usize, old_len: usize, new_index: usize) {
        self.flush_eq();
        if let Some((a, b, c)) = self.del.take() {
            self.del = Some((a, b + old_len, c));
        } else {
            self.del = Some((old_index, old_len, new_index));
        }
    }
    fn insert(&mut self, old_index: usize, new_index: usize, new_len: usize) {
        self.flush_eq();
        self.ins = Some(match self.ins.take() {
            Some((a, b, c)) => (a, b, c + new_len),
            None => (old_index, new_index, new_len),
        });
    }
    fn finish(mut self) -> Vec<DiffOp> {
        self.flush_eq();
        self.flush_del_ins();
        self.ops
    }
}

struct V {
    offset: isize,
    v: Vec<usize>,
}

impl V {
    fn new(max_d: usize) -> Self {
        V { offset: max_d as isize, v: vec![0; 2 * max_d] }
    }
    fn len(&self) -> usize {
        self.v.len()
    }
}

impl std::ops::Index<isize> for V {
    type Output = usize;
    fn index(&self, index: isize) -> &usize {
        &self.v[(index + self.offset) as usize]
    }
}
impl std::ops::IndexMut<isize> for V {
    fn index_mut(&mut self, index: isize) -> &mut usize {
        &mut self.v[(index + self.offset) as usize]
    }
}

fn max_d(len1: usize, len2: usize) -> usize {
    (len1 + len2 + 1) / 2 + 1
}

fn split_at(range: Range<usize>, at: usize) -> (Range<usize>, Range<usize>) {
    (range.start..at, at..range.end)
}

fn common_prefix_len<T: PartialEq>(old: &[T], old_range: Range<usize>, new: &[T], new_range: Range<usize>) -> usize {
    if old_range.is_empty() || new_range.is_empty() {
        return 0;
    }
    new_range
        .zip(old_range)
        .take_while(|x| new[x.0] == old[x.1])
        .count()
}

fn common_suffix_len<T: PartialEq>(old: &[T], old_range: Range<usize>, new: &[T], new_range: Range<usize>) -> usize {
    if old_range.is_empty() || new_range.is_empty() {
        return 0;
    }
    new_range
        .rev()
        .zip(old_range.rev())
        .take_while(|x| new[x.0] == old[x.1])
        .count()
}

#[allow(clippy::too_many_arguments)]
fn find_middle_snake<T: PartialEq>(
    old: &[T],
    old_range: Range<usize>,
    new: &[T],
    new_range: Range<usize>,
    vf: &mut V,
    vb: &mut V,
    deadline: Option<Instant>,
) -> Option<(usize, usize)> {
    let n = old_range.len();
    let m = new_range.len();
    let delta = n as isize - m as isize;
    let odd = delta & 1 == 1;

    // reset
    vf.v.iter_mut().for_each(|x| *x = 0);
    vb.v.iter_mut().for_each(|x| *x = 0);
    vf[1] = 0;
    vb[1] = 0;

    let d_max = max_d(n, m);
    assert!(vf.len() >= d_max);
    assert!(vb.len() >= d_max);

    for d in 0..d_max as isize {
        if let Some(deadline) = deadline {
            if Instant::now() > deadline {
                break;
            }
        }
        // forward path
        let mut k = d;
        while k >= -d {
            let mut x = if k == -d || (k != d && vf[k - 1] < vf[k + 1]) {
                vf[k + 1]
            } else {
                vf[k - 1] + 1
            };
            let y = (x as isize - k) as usize;
            let (x0, y0) = (x, y);
            if x < n && y < m {
                let advance = common_prefix_len(old, old_range.start + x..old_range.end, new, new_range.start + y..new_range.end);
                x += advance;
            }
            vf[k] = x;
            if odd && (k - delta).abs() <= (d - 1) {
                if vf[k] + vb[-(k - delta)] >= n {
                    return Some((x0 + old_range.start, y0 + new_range.start));
                }
            }
            k -= 2;
        }
        // backward path
        let mut k = d;
        while k >= -d {
            let mut x = if k == -d || (k != d && vb[k - 1] < vb[k + 1]) {
                vb[k + 1]
            } else {
                vb[k - 1] + 1
            };
            let mut y = (x as isize - k) as usize;
            if x < n && y < m {
                let advance = common_suffix_len(old, old_range.start..old_range.start + n - x, new, new_range.start..new_range.start + m - y);
                x += advance;
                y += advance;
            }
            vb[k] = x;
            if !odd && (k - delta).abs() <= d {
                if vb[k] + vf[-(k - delta)] >= n {
                    return Some((n - x + old_range.start, m - y + new_range.start));
                }
            }
            k -= 2;
        }
    }
    None
}

#[allow(clippy::too_many_arguments)]
fn conquer<T: PartialEq>(
    d: &mut Replace,
    old: &[T],
    mut old_range: Range<usize>,
    new: &[T],
    mut new_range: Range<usize>,
    vf: &mut V,
    vb: &mut V,
    deadline: Option<Instant>,
) {
    let common_prefix_len = common_prefix_len(old, old_range.clone(), new, new_range.clone());
    if common_prefix_len > 0 {
        d.equal(old_range.start, new_range.start, common_prefix_len);
    }
    old_range.start += common_prefix_len;
    new_range.start += common_prefix_len;

    let common_suffix_len = common_suffix_len(old, old_range.clone(), new, new_range.clone());
    let common_suffix = (old_range.end - common_suffix_len, new_range.end - common_suffix_len);
    old_range.end -= common_suffix_len;
    new_range.end -= common_suffix_len;

    if old_range.is_empty() && new_range.is_empty() {
        // nothing
    } else if new_range.is_empty() {
        d.delete(old_range.start, old_range.len(), new_range.start);
    } else if old_range.is_empty() {
        d.insert(old_range.start, new_range.start, new_range.len());
    } else if let Some((x_start, y_start)) =
        find_middle_snake(old, old_range.clone(), new, new_range.clone(), vf, vb, deadline)
    {
        let (old_a, old_b) = split_at(old_range, x_start);
        let (new_a, new_b) = split_at(new_range, y_start);
        conquer(d, old, old_a, new, new_a, vf, vb, deadline);
        conquer(d, old, old_b, new, new_b, vf, vb, deadline);
    } else {
        d.delete(old_range.start, old_range.end - old_range.start, new_range.start);
        d.insert(old_range.start, new_range.start, new_range.end - new_range.start);
    }

    if common_suffix_len > 0 {
        d.equal(common_suffix.0, common_suffix.1, common_suffix_len);
    }
}

/// Compute grouped diff ops between two slices.
pub fn diff_ops<T: PartialEq>(old: &[T], new: &[T], deadline: Option<Instant>) -> Vec<DiffOp> {
    let mut d = Replace::new();
    let max_d = max_d(old.len(), new.len());
    let mut vb = V::new(max_d);
    let mut vf = V::new(max_d);
    conquer(&mut d, old, 0..old.len(), new, 0..new.len(), &mut vf, &mut vb, deadline);
    d.finish()
}

/// Ratio of matched tokens (2*matches / total)
pub fn diff_ratio(ops: &[DiffOp], old_len: usize, new_len: usize) -> f32 {
    let matches: usize = ops
        .iter()
        .map(|op| match op {
            DiffOp::Equal { len, .. } => *len,
            _ => 0,
        })
        .sum();
    let len = old_len + new_len;
    if len == 0 {
        1.0
    } else {
        2.0 * matches as f32 / len as f32
    }
}

/// Split text into lines, keeping the line terminators.
pub fn tokenize_lines(s: &str) -> Vec<&str> {
    let mut iter = s.char_indices().peekable();
    let mut rv = vec![];
    let mut last_pos = 0;
    while let Some((idx, c)) = iter.next() {
        if c == '\r' {
            if iter.peek().map_or(false, |x| x.1 == '\n') {
                rv.push(&s[last_pos..=idx + 1]);
                iter.next();
                last_pos = idx + 2;
            } else {
                rv.push(&s[last_pos..=idx]);
                last_pos = idx + 1;
            }
        } else if c == '\n' {
            rv.push(&s[last_pos..=idx]);
            last_pos = idx + 1;
        }
    }
    if last_pos < s.len() {
        rv.push(&s[last_pos..]);
    }
    rv
}

/// Split into unicode words (word boundaries).
pub fn tokenize_unicode_words(s: &str) -> Vec<&str> {
    use unicode_segmentation::UnicodeSegmentation;
    s.split_word_bounds().collect()
}

pub fn ends_with_newline(s: &str) -> bool {
    s.ends_with('\n') || s.ends_with('\r')
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ChangeTag {
    Equal,
    Delete,
    Insert,
}

/// A line-level change with optional inline emphasis.
#[derive(Debug, Clone)]
pub struct InlineChange<'a> {
    pub tag: ChangeTag,
    pub old_index: Option<usize>,
    pub new_index: Option<usize>,
    /// (emphasized, text)
    pub values: Vec<(bool, &'a str)>,
}

impl<'a> InlineChange<'a> {
    pub fn text(&self) -> String {
        self.values.iter().map(|x| x.1).collect()
    }
}

struct MultiLookup<'bufs, 's> {
    strings: &'bufs [&'s str],
    seqs: Vec<(&'s str, usize, usize)>,
}

impl<'bufs, 's> MultiLookup<'bufs, 's> {
    fn new(strings: &'bufs [&'s str]) -> Self {
        let mut seqs = Vec::new();
        for (string_idx, string) in strings.iter().enumerate() {
            let mut offset = 0;
            for word in tokenize_unicode_words(string) {
                seqs.push((word, string_idx, offset));
                offset += word.len();
            }
        }
        MultiLookup { strings, seqs }
    }
    fn len(&self) -> usize {
        self.seqs.len()
    }
    fn tokens(&self) -> Vec<&'s str> {
        self.seqs.iter().map(|x| x.0).collect()
    }
    fn get_original_slices(&self, idx: usize, len: usize) -> Vec<(usize, &'s str)> {
        let mut last = None;
        let mut rv = Vec::new();
        for offset in 0..len {
            let (s, str_idx, char_idx) = self.seqs[idx + offset];
            last = match last {
                None => Some((str_idx, char_idx, s.len())),
                Some((last_str_idx, start_char_idx, last_len)) => {
                    if last_str_idx == str_idx {
                        Some((str_idx, start_char_idx, last_len + s.len()))
                    } else {
                        rv.push((
                            last_str_idx,
                            &self.strings[last_str_idx][start_char_idx..start_char_idx + last_len],
                        ));
                        Some((str_idx, char_idx, s.len()))
                    }
                }
            };
        }
        if let Some((str_idx, start_char_idx, len)) = last {
            rv.push((str_idx, &self.strings[str_idx][start_char_idx..start_char_idx + len]));
        }
        rv
    }
}

fn push_values<'s>(v: &mut Vec<Vec<(bool, &'s str)>>, idx: usize, emphasized: bool, s: &'s str) {
    v.resize_with(v.len().max(idx + 1), Vec::new);
    v[idx].push((emphasized, s));
}

/// Plain (non-inline) changes for an op.
pub fn iter_changes<'a>(op: &DiffOp, old: &[&'a str], new: &[&'a str]) -> Vec<InlineChange<'a>> {
    let mut rv = vec![];
    match *op {
        DiffOp::Equal { old_index, new_index, len } => {
            for i in 0..len {
                rv.push(InlineChange {
                    tag: ChangeTag::Equal,
                    old_index: Some(old_index + i),
                    new_index: Some(new_index + i),
                    values: vec![(false, old[old_index + i])],
                });
            }
        }
        DiffOp::Delete { old_index, old_len, .. } => {
            for i in 0..old_len {
                rv.push(InlineChange {
                    tag: ChangeTag::Delete,
                    old_index: Some(old_index + i),
                    new_index: None,
                    values: vec![(false, old[old_index + i])],
                });
            }
        }
        DiffOp::Insert { new_index, new_len, .. } => {
            for i in 0..new_len {
                rv.push(InlineChange {
                    tag: ChangeTag::Insert,
                    old_index: None,
                    new_index: Some(new_index + i),
                    values: vec![(false, new[new_index + i])],
                });
            }
        }
        DiffOp::Replace { old_index, old_len, new_index, new_len } => {
            for i in 0..old_len {
                rv.push(InlineChange {
                    tag: ChangeTag::Delete,
                    old_index: Some(old_index + i),
                    new_index: None,
                    values: vec![(false, old[old_index + i])],
                });
            }
            for i in 0..new_len {
                rv.push(InlineChange {
                    tag: ChangeTag::Insert,
                    old_index: None,
                    new_index: Some(new_index + i),
                    values: vec![(false, new[new_index + i])],
                });
            }
        }
    }
    rv
}

/// Inline (word-level emphasized) changes for an op.
pub fn iter_inline_changes<'a>(
    op: &DiffOp,
    old: &[&'a str],
    new: &[&'a str],
    deadline: Option<Instant>,
) -> Vec<InlineChange<'a>> {
    let (tag, old_range, new_range) = (op.tag(), op.old_range(), op.new_range());
    if tag != Tag::Replace {
        return iter_changes(op, old, new);
    }

    let old_slices = &old[old_range.clone()];
    let new_slices = &new[new_range.clone()];

    let old_lookup = MultiLookup::new(old_slices);
    let new_lookup = MultiLookup::new(new_slices);
    let old_tokens = old_lookup.tokens();
    let new_tokens = new_lookup.tokens();

    let ops = diff_ops(&old_tokens, &new_tokens, deadline);

    if diff_ratio(&ops, old_lookup.len(), new_lookup.len()) < 0.5 {
        return iter_changes(op, old, new);
    }

    let mut old_values: Vec<Vec<(bool, &str)>> = Vec::new();
    let mut new_values: Vec<Vec<(bool, &str)>> = Vec::new();

    for op in ops {
        match op {
            DiffOp::Equal { old_index, len, new_index } => {
                for (idx, slice) in old_lookup.get_original_slices(old_index, len) {
                    push_values(&mut old_values, idx, false, slice);
                }
                for (idx, slice) in new_lookup.get_original_slices(new_index, len) {
                    push_values(&mut new_values, idx, false, slice);
                }
            }
            DiffOp::Delete { old_index, old_len, .. } => {
                for (idx, slice) in old_lookup.get_original_slices(old_index, old_len) {
                    push_values(&mut old_values, idx, true, slice);
                }
            }
            DiffOp::Insert { new_index, new_len, .. } => {
                for (idx, slice) in new_lookup.get_original_slices(new_index, new_len) {
                    push_values(&mut new_values, idx, true, slice);
                }
            }
            DiffOp::Replace { old_index, old_len, new_index, new_len } => {
                for (idx, slice) in old_lookup.get_original_slices(old_index, old_len) {
                    push_values(&mut old_values, idx, true, slice);
                }
                for (idx, slice) in new_lookup.get_original_slices(new_index, new_len) {
                    push_values(&mut new_values, idx, true, slice);
                }
            }
        }
    }

    let mut rv = Vec::new();
    for (idx, values) in old_values.into_iter().enumerate() {
        rv.push(InlineChange {
            tag: ChangeTag::Delete,
            old_index: Some(old_range.start + idx),
            new_index: None,
            values,
        });
    }
    for (idx, values) in new_values.into_iter().enumerate() {
        rv.push(InlineChange {
            tag: ChangeTag::Insert,
            old_index: None,
            new_index: Some(new_range.start + idx),
            values,
        });
    }
    rv
}

/// Default deadline used for text diffs.
pub fn default_deadline() -> Option<Instant> {
    Some(Instant::now() + Duration::from_millis(500))
}
