use crate::common::{now_string, CommandResult};
use std::io::Read;
use std::process::{Command, Stdio};
use std::sync::{Arc, Mutex};
use std::thread;

#[derive(Debug)]
pub struct ParseError;

pub struct ExecConfig {
    pub command: Vec<String>,
    pub shell_command: String,
    pub is_exec: bool,
}

impl ExecConfig {
    /// Build the process command line (program + args).
    pub fn build(&self) -> Vec<String> {
        let command_str = self.command.join(" ");
        if self.is_exec {
            // split the joined command into shell words
            let words: Result<Vec<String>, ParseError> =
                shlex::split(&command_str).ok_or(ParseError);
            return words.expect("shell command parse error.");
        }
        let mut shell_words: Vec<String> = shlex::split(&self.shell_command).unwrap_or_default();
        let mut is_replaced = false;
        for w in shell_words.iter_mut() {
            if w.contains("{COMMAND}") {
                *w = w.replace("{COMMAND}", &command_str);
                is_replaced = true;
            }
        }
        if !is_replaced {
            shell_words.push(command_str);
        }
        shell_words
    }

    pub fn command_string(&self) -> String {
        self.command.join(" ")
    }
}

/// Run the command once and collect the result.
pub fn exec_once(config: &ExecConfig) -> CommandResult {
    let argv = config.build();
    let command_string = config.command_string();
    let mut result = CommandResult {
        timestamp: String::new(),
        command: command_string,
        status: true,
        output: String::new(),
        stdout: String::new(),
        stderr: String::new(),
    };

    if argv.is_empty() {
        result.timestamp = now_string();
        result.status = false;
        return result;
    }

    let child = Command::new(&argv[0])
        .args(&argv[1..])
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn();

    match child {
        Ok(mut child) => {
            let combined: Arc<Mutex<Vec<u8>>> = Arc::new(Mutex::new(Vec::new()));
            let mut child_stdout = child.stdout.take().unwrap();
            let mut child_stderr = child.stderr.take().unwrap();

            let c1 = combined.clone();
            let t_out = thread::spawn(move || {
                let mut all = Vec::new();
                let mut buf = [0u8; 4096];
                loop {
                    match child_stdout.read(&mut buf) {
                        Ok(0) | Err(_) => break,
                        Ok(n) => {
                            all.extend_from_slice(&buf[..n]);
                            c1.lock().unwrap().extend_from_slice(&buf[..n]);
                        }
                    }
                }
                all
            });
            let c2 = combined.clone();
            let t_err = thread::spawn(move || {
                let mut all = Vec::new();
                let mut buf = [0u8; 4096];
                loop {
                    match child_stderr.read(&mut buf) {
                        Ok(0) | Err(_) => break,
                        Ok(n) => {
                            all.extend_from_slice(&buf[..n]);
                            c2.lock().unwrap().extend_from_slice(&buf[..n]);
                        }
                    }
                }
                all
            });
            let out = t_out.join().unwrap_or_default();
            let err = t_err.join().unwrap_or_default();
            let status = child.wait().map(|s| s.success()).unwrap_or(false);
            let all = combined.lock().unwrap().clone();

            result.timestamp = now_string();
            result.status = status;
            result.output = String::from_utf8_lossy(&all).to_string();
            result.stdout = String::from_utf8_lossy(&out).to_string();
            result.stderr = String::from_utf8_lossy(&err).to_string();
        }
        Err(e) => {
            result.timestamp = now_string();
            result.status = false;
            result.output = e.to_string();
            result.stdout = e.to_string();
            result.stderr = e.to_string();
        }
    }
    result
}

/// Run the "after command" with HWATCH_DATA environment variable.
pub fn exec_after_command(after_command: &str, before: &CommandResult, after: &CommandResult) {
    let data = serde_json::json!({
        "before_result": before,
        "after_result": after,
    });
    let _ = Command::new("sh")
        .arg("-c")
        .arg(after_command)
        .env("HWATCH_DATA", data.to_string())
        .stdin(Stdio::null())
        .status();
}
