//! ANSI escape sequence handling: parsing SGR sequences into styles,
//! escaping control characters for display, tab expansion.

use ratatui::style::{Color, Modifier, Style};
use unicode_width::UnicodeWidthChar;

/// Remove OSC sequences (ESC ] ... BEL | ESC \).
pub fn remove_osc(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    let chars: Vec<char> = text.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '\x1b' && i + 1 < chars.len() && chars[i + 1] == ']' {
            // skip until BEL or ESC \
            let mut j = i + 2;
            let mut found = false;
            while j < chars.len() {
                if chars[j] == '\x07' {
                    j += 1;
                    found = true;
                    break;
                }
                if chars[j] == '\x1b' && j + 1 < chars.len() && chars[j + 1] == '\\' {
                    j += 2;
                    found = true;
                    break;
                }
                j += 1;
            }
            if found {
                i = j;
                continue;
            } else {
                i = chars.len();
                continue;
            }
        }
        out.push(c);
        i += 1;
    }
    out
}

fn is_escaped_control(c: char) -> bool {
    if c == '\t' || c == '\n' || c == '\r' || c == '\x1b' {
        return false;
    }
    if c.is_control() {
        return true;
    }
    matches!(UnicodeWidthChar::width(c), Some(0))
}

fn push_escaped_char(out: &mut String, c: char) {
    let mut buf = [0u8; 4];
    let s = c.encode_utf8(&mut buf);
    for b in s.bytes() {
        out.push_str(&format!("\\x{:02x}", b));
    }
}

/// Escape control characters (except tab/newline/CR/ESC) as `\xNN`.
pub fn escape_control_chars(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    for c in text.chars() {
        if is_escaped_control(c) {
            push_escaped_char(&mut out, c);
        } else {
            out.push(c);
        }
    }
    out
}

/// Expand tabs to spaces (column counted in chars, per line).
pub fn expand_tabs(text: &str, tab_size: usize) -> String {
    let mut out = String::with_capacity(text.len());
    let mut col = 0usize;
    for c in text.chars() {
        match c {
            '\n' => {
                out.push('\n');
                col = 0;
            }
            '\t' => {
                if tab_size == 0 {
                    continue;
                }
                let n = tab_size - (col % tab_size);
                for _ in 0..n {
                    out.push(' ');
                }
                col += n;
            }
            _ => {
                out.push(c);
                col += 1;
            }
        }
    }
    out
}

/// Escape ESC characters as literal `\x1b`.
pub fn escape_esc(text: &str) -> String {
    text.replace('\x1b', "\\x1b")
}

/// Common preprocessing of command output for display (both modes).
pub fn preprocess(text: &str, tab_size: usize) -> String {
    let t = remove_osc(text);
    let t = escape_control_chars(&t);
    expand_tabs(&t, tab_size)
}

/// Full processing for non-color display.
pub fn to_plain_text(text: &str, tab_size: usize) -> String {
    escape_esc(&preprocess(text, tab_size))
}

fn ansi_basic_color(n: u8) -> Color {
    match n {
        0 => Color::Black,
        1 => Color::Red,
        2 => Color::Green,
        3 => Color::Yellow,
        4 => Color::Blue,
        5 => Color::Magenta,
        6 => Color::Cyan,
        7 => Color::Gray,
        8 => Color::DarkGray,
        9 => Color::LightRed,
        10 => Color::LightGreen,
        11 => Color::LightYellow,
        12 => Color::LightBlue,
        13 => Color::LightMagenta,
        14 => Color::LightCyan,
        _ => Color::White,
    }
}

/// Parse SGR parameters and apply them to a style.
/// Returns (new style, number of logical params processed).
pub fn apply_sgr(style: Style, params: &str) -> (Style, usize) {
    let mut style = style;
    let parts: Vec<&str> = params.split(';').collect();
    let nums: Vec<Option<u32>> = parts
        .iter()
        .map(|p| if p.is_empty() { None } else { p.parse::<u32>().ok() })
        .collect();
    if params.is_empty() {
        return (Style::default(), 1);
    }
    let mut count = 0usize;
    let mut i = 0;
    while i < nums.len() {
        let n = match nums[i] {
            Some(n) => n,
            None => {
                // empty param: skipped
                i += 1;
                continue;
            }
        };
        count += 1;
        match n {
            0 => style = Style::default(),
            1 => style = style.add_modifier(Modifier::BOLD),
            2 => {
                style = style.remove_modifier(Modifier::BOLD);
                style = style.add_modifier(Modifier::DIM);
            }
            3 => style = style.add_modifier(Modifier::ITALIC),
            4 => style = style.add_modifier(Modifier::UNDERLINED),
            5 => style = style.add_modifier(Modifier::SLOW_BLINK),
            6 => style = style.add_modifier(Modifier::RAPID_BLINK),
            7 => style = style.add_modifier(Modifier::REVERSED),
            8 => {}
            9 => style = style.add_modifier(Modifier::CROSSED_OUT),
            21 => style = style.add_modifier(Modifier::UNDERLINED),
            22 => {
                style = style.remove_modifier(Modifier::BOLD);
                style = style.remove_modifier(Modifier::DIM);
            }
            23 => style = style.remove_modifier(Modifier::ITALIC),
            24 => style = style.remove_modifier(Modifier::UNDERLINED),
            25 => {
                style = style.remove_modifier(Modifier::SLOW_BLINK);
                style = style.remove_modifier(Modifier::RAPID_BLINK);
            }
            27 => style = style.remove_modifier(Modifier::REVERSED),
            28 => {}
            29 => style = style.remove_modifier(Modifier::CROSSED_OUT),
            30..=37 => style = style.fg(ansi_basic_color((n - 30) as u8)),
            38 | 48 => {
                // extended color
                if i + 1 < nums.len() {
                    match nums[i + 1] {
                        Some(5) => {
                            if i + 2 < nums.len() {
                                if let Some(idx) = nums[i + 2] {
                                    if idx <= 255 {
                                        let color = Color::Indexed(idx as u8);
                                        if n == 38 {
                                            style = style.fg(color);
                                        } else {
