    let mut style = Style::default();
    let mut cur = String::new();
    let mut i = 0;
    let flush = |cur: &mut String, items: &mut Vec<AnsiItem>, style: Style| {
        if !cur.is_empty() {
            items.push(AnsiItem::Text(std::mem::take(cur), style));
        }
    };
