            } else {
                // unknown escape: literal
                cur.push_str("\\x1b");
                i += 1;
                continue;
            }
        }
        if c == '\r' {
            // carriage return is dropped in color mode
            i += 1;
            continue;
        }
        cur.push(c);
        i += 1;
    }
    flush(&mut cur, &mut items, style);
    items
}

