            40..=47 => style = style.bg(ansi_basic_color((n - 40) as u8)),
            49 => style.bg = Some(Color::Reset),
            90..=97 => style = style.fg(ansi_basic_color((n - 90 + 8) as u8)),
            100..=107 => style = style.bg(ansi_basic_color((n - 100 + 8) as u8)),
            _ => {}
        }
        i += 1;
    }
    if count == 0 {
        count = 1;
    }
    (style, count)
}

