//! Generation of display lines (plain / watch diff / line diff / word diff).

use crate::ansi;
use crate::common::DiffMode;
use crate::myers;
use ratatui::style::{Color, Modifier, Style};
use ratatui::text::{Line, Span};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Target {
    Batch,
    Tui,
}

pub const COLOR_DEL_LINENUM: Color = Color::Rgb(118, 0, 0);
pub const COLOR_ADD_LINENUM: Color = Color::Rgb(56, 119, 120);
pub const COLOR_LINENUM: Color = Color::DarkGray;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LineKind {
    Plain,
    Equal,
    Delete,
    Insert,
}

/// A display line with optional line number.
#[derive(Debug, Clone)]
pub struct DispLine {
    pub spans: Vec<Span<'static>>,
    pub number: Option<usize>,
    pub kind: LineKind,
}

impl DispLine {
    pub fn into_line(self) -> Line<'static> {
        Line::from(self.spans)
    }
}

/// Options for line generation.
#[derive(Debug, Clone)]
pub struct GenOptions {
    pub color: bool,
    pub line_number: bool,
    pub only_diff: bool,
    pub tab_size: usize,
    pub target: Target,
}

fn text_to_spans(line: &str, color: bool) -> Vec<Span<'static>> {
    if color {
        ansi::ansi_to_spans(line)
    } else {
        vec![Span::raw(ansi::escape_esc(line))]
    }
}

/// Plain (no diff) lines.
pub fn gen_plain(text: &str, opts: &GenOptions) -> Vec<DispLine> {
    let processed = ansi::preprocess(text, opts.tab_size);
    let lines: Vec<&str> = match opts.target {
        Target::Batch => processed.split('\n').collect(),
        Target::Tui => processed.lines().collect(),
    };
    lines
        .iter()
        .enumerate()
        .map(|(i, l)| DispLine {
            spans: text_to_spans(l, opts.color),
            number: Some(i + 1),
            kind: LineKind::Plain,
        })
        .collect()
}

// ---------------------------------------------------------------------------
// watch diff
// ---------------------------------------------------------------------------

fn watch_diff_line_plain(old_line: Option<&str>, new_line: Option<&str>, target: Target) -> Vec<Span<'static>> {
    let old_s = old_line.unwrap_or("");
    let new_s = new_line.unwrap_or("");
    if old_line.is_some() && new_line.is_some() && old_s == new_s {
        return vec![Span::raw(new_s.to_string())];
    }
    // empty new line marker
    let new_s: String = if new_line.is_some() && new_s.is_empty() {
        "\u{200b}".to_string()
    } else {
        new_s.to_string()
    };
    let old_chars: Vec<char> = old_s.chars().collect();
    let new_chars: Vec<char> = new_s.chars().collect();
    let max_len = std::cmp::max(old_chars.len(), new_chars.len());
    let mut spans: Vec<Span<'static>> = vec![];
    let mut in_esc = false;
    let mut esc_buf = String::new();
    for i in 0..max_len {
        let oc = old_chars.get(i).copied().unwrap_or(' ');
        let nc = new_chars.get(i).copied().unwrap_or(' ');
        if oc == nc {
            spans.push(Span::raw(nc.to_string()));
            continue;
        }
        if nc == '\x1b' {
            in_esc = true;
            esc_buf.clear();
            esc_buf.push(nc);
            continue;
        }
        if in_esc {
            esc_buf.push(nc);
            spans.push(Span::raw(esc_buf.clone()));
            if nc == 'm' {
                in_esc = false;
                esc_buf.clear();
            }
            continue;
        }
        spans.push(Span::styled(nc.to_string(), Style::default().add_modifier(Modifier::REVERSED)));
    }
    match target {
        Target::Batch => spans.push(Span::raw("\x1b[0m")),
        Target::Tui => {}
    }
    spans
}

#[derive(Debug, Clone, PartialEq)]
enum Token {
    Virtual,
    Char(char, Style),
}

fn color_tokens(line: &str) -> Vec<Token> {
    let mut tokens = vec![];
    let mut last_sgr: Option<usize> = None;
    for item in ansi::parse_ansi(line) {
        match item {
            ansi::AnsiItem::Sgr(n) => last_sgr = Some(n),
            ansi::AnsiItem::Text(t, style) => {
                for c in t.chars() {
                    if let Some(n) = last_sgr {
                        for _ in 0..(1 + n) {
                            tokens.push(Token::Virtual);
                        }
                    }
                    tokens.push(Token::Char(c, style));
                }
            }
        }
    }
    tokens
}

fn watch_diff_line_color(old_line: Option<&str>, new_line: Option<&str>) -> Vec<Span<'static>> {
    let old_s = old_line.unwrap_or("");
    let new_s = new_line.unwrap_or("");
    if old_line.is_some() && new_line.is_some() && old_s == new_s {
        return ansi::ansi_to_spans(new_s);
    }
    let new_s: String = if new_line.is_some() && new_s.is_empty() {
        "\u{200b}".to_string()
    } else {
        new_s.to_string()
    };
    let old_tokens = color_tokens(old_s);
    let new_tokens = color_tokens(&new_s);
    let max_len = std::cmp::max(old_tokens.len(), new_tokens.len());
    let mut spans: Vec<Span<'static>> = vec![];
    for i in 0..max_len {
        let nt = new_tokens.get(i).cloned().unwrap_or(Token::Char(' ', Style::default()));
        let ot = old_tokens.get(i).cloned();
        match nt {
            Token::Virtual => {}
            Token::Char(c, style) => {
                if Some(Token::Char(c, style)) == ot {
                    spans.push(Span::styled(c.to_string(), style));
                } else {
                    spans.push(Span::styled(c.to_string(), style.add_modifier(Modifier::REVERSED)));
                }
            }
        }
    }
    spans.push(Span::raw("\u{a0}"));
    spans
}

fn split_lines_for_diff<'a>(text: &'a str, target: Target) -> Vec<&'a str> {
    match target {
        Target::Batch => text.lines().collect(),
        Target::Tui => text.trim_end_matches('\n').lines().collect(),
    }
}

pub fn gen_watch_diff(old_text: &str, new_text: &str, opts: &GenOptions) -> Vec<DispLine> {
    let old_p = ansi::preprocess(old_text, opts.tab_size);
    let new_p = ansi::preprocess(new_text, opts.tab_size);
    let (old_p, new_p) = if opts.color {
        (old_p, new_p)
    } else {
        match opts.target {
            Target::Batch => (old_p, new_p),
            Target::Tui => (ansi::escape_esc(&old_p), ansi::escape_esc(&new_p)),
        }
    };
    let old_lines = split_lines_for_diff(&old_p, opts.target);
    let new_lines = split_lines_for_diff(&new_p, opts.target);
    let max_len = std::cmp::max(old_lines.len(), new_lines.len());
    let mut result = vec![];
    for i in 0..max_len {
        let ol = old_lines.get(i).copied();
        let nl = new_lines.get(i).copied();
        let spans = if opts.color {
            watch_diff_line_color(ol, nl)
        } else {
            watch_diff_line_plain(ol, nl, opts.target)
        };
        result.push(DispLine { spans, number: Some(i + 1), kind: LineKind::Plain });
    }
    result
}

// ---------------------------------------------------------------------------
// line / word diff
// ---------------------------------------------------------------------------

pub fn gen_line_diff(old_text: &str, new_text: &str, mode: DiffMode, opts: &GenOptions) -> Vec<DispLine> {
    let old_p = ansi::preprocess(old_text, opts.tab_size);
    let new_p = ansi::preprocess(new_text, opts.tab_size);
    let (old_p, new_p) = match opts.target {
        Target::Batch => (old_p, new_p),
        Target::Tui => (
            old_p.trim_end_matches('\n').to_string(),
            new_p.trim_end_matches('\n').to_string(),
        ),
    };
    let old_lines = myers::tokenize_lines(&old_p);
    let new_lines = myers::tokenize_lines(&new_p);
    let deadline = myers::default_deadline();
    let ops = myers::diff_ops(&old_lines, &new_lines, deadline);

    let is_word = mode == DiffMode::Word;
    let mut result: Vec<DispLine> = vec![];
    for op in ops.iter() {
        let changes = myers::iter_inline_changes(op, &old_lines, &new_lines, deadline);
        for change in changes {
            match change.tag {
                myers::ChangeTag::Equal => {
                    if opts.only_diff {
                        continue;
                    }
                    let text = change.text();
                    let text = text.trim_end_matches(|c| c == '\n' || c == '\r');
                    let mut spans = vec![Span::raw("   ")];
                    spans.extend(text_to_spans(text, opts.color));
                    result.push(DispLine {
                        spans,
                        number: change.old_index.map(|x| x + 1),
                        kind: LineKind::Equal,
                    });
                }
                myers::ChangeTag::Delete | myers::ChangeTag::Insert => {
                    let is_del = change.tag == myers::ChangeTag::Delete;
                    let line_color = if is_del { Color::Red } else { Color::Green };
                    let prefix = if is_del { "-  " } else { "+  " };
                    let mut spans = vec![Span::styled(prefix, Style::default().fg(line_color))];
                    for (emphasized, value) in change.values.iter() {
                        let value = value.trim_end_matches(|c| c == '\n' || c == '\r');
                        let value = ansi::strip_ansi(value);
                        let style = if *emphasized && is_word {
                            Style::default()
                                .fg(line_color)
                                .bg(Color::White)
                                .add_modifier(Modifier::REVERSED)
                        } else {
                            Style::default().fg(line_color)
                        };
                        spans.push(Span::styled(value, style));
                    }
                    result.push(DispLine {
                        spans,
                        number: if is_del {
                            change.old_index.map(|x| x + 1)
                        } else {
                            change.new_index.map(|x| x + 1)
                        },
                        kind: if is_del { LineKind::Delete } else { LineKind::Insert },
                    });
                }
            }
        }
    }
    result
}

/// Add line numbers to lines.
pub fn add_line_numbers(lines: Vec<DispLine>, color_numbers: bool) -> Vec<DispLine> {
    let max_num = lines.iter().filter_map(|l| l.number).max().unwrap_or(0);
    let count = lines.len();
    let width = std::cmp::max(max_num, count).to_string().len();
    lines
        .into_iter()
        .map(|mut l| {
            let n = l.number.unwrap_or(0);
            let color = if color_numbers {
                match l.kind {
                    LineKind::Delete => COLOR_DEL_LINENUM,
                    LineKind::Insert => COLOR_ADD_LINENUM,
                    _ => COLOR_LINENUM,
                }
            } else {
                COLOR_LINENUM
            };
            let num_str = n.to_string();
            let pad = width.saturating_sub(num_str.len());
            let mut spans = vec![];
            if pad > 0 {
                spans.push(Span::raw(" ".repeat(pad)));
            }
            spans.push(Span::styled(num_str, Style::default().fg(color)));
            spans.push(Span::styled(" | ", Style::default().fg(color)));
            spans.extend(l.spans.drain(..));
            l.spans = spans;
            l
        })
        .collect()
}

/// Generate lines for a given mode.
pub fn gen_lines(old_text: Option<&str>, new_text: &str, mode: DiffMode, opts: &GenOptions) -> Vec<DispLine> {
    let mut lines = match mode {
        DiffMode::Disable => gen_plain(new_text, opts),
        DiffMode::Watch => gen_watch_diff(old_text.unwrap_or(""), new_text, opts),
        DiffMode::Line | DiffMode::Word => gen_line_diff(old_text.unwrap_or(""), new_text, mode, opts),
    };
    if opts.line_number {
        lines = add_line_numbers(lines, matches!(mode, DiffMode::Line | DiffMode::Word));
    }
    lines
}

// ---------------------------------------------------------------------------
// batch output conversion
// ---------------------------------------------------------------------------

fn color_code(color: Color, is_fg: bool) -> String {
    let base: u8 = if is_fg { 30 } else { 40 };
    match color {
        Color::Reset => if is_fg { "39".to_string() } else { "49".to_string() },
        Color::Black => (base).to_string(),
        Color::Red => (base + 1).to_string(),
        Color::Green => (base + 2).to_string(),
        Color::Yellow => (base + 3).to_string(),
        Color::Blue => (base + 4).to_string(),
        Color::Magenta => (base + 5).to_string(),
        Color::Cyan => (base + 6).to_string(),
        Color::Gray => (base + 7).to_string(),
        Color::White => (base + 7).to_string(),
        Color::DarkGray => format!("{};5;240", base + 8),
        Color::LightRed => (base + 61).to_string(),
        Color::LightGreen => (base + 62).to_string(),
        Color::LightYellow => (base + 63).to_string(),
        Color::LightBlue => (base + 64).to_string(),
        Color::LightMagenta => (base + 65).to_string(),
        Color::LightCyan => (base + 66).to_string(),
        Color::Indexed(i) => format!("{};5;{}", base + 8, i),
        Color::Rgb(r, g, b) => format!("{};2;{};{};{}", base + 8, r, g, b),
    }
}

/// Convert a span to an ANSI string for batch output.
pub fn span_to_ansi(span: &Span) -> String {
    let style = span.style;
    let content = span.content.to_string();
    let reversed = style.add_modifier.contains(Modifier::REVERSED);
    let (mut fg, mut bg) = (style.fg, style.bg);
    if reversed && (fg.is_some() || bg.is_some()) {
        std::mem::swap(&mut fg, &mut bg);
    }
    let mut codes: Vec<String> = vec![];
    if let Some(bg) = bg {
        codes.push(color_code(bg, false));
    }
    if let Some(fg) = fg {
        codes.push(color_code(fg, true));
    }
    if codes.is_empty() {
        if reversed {
            return format!("\x1b[7m{}\x1b[7m", content);
        }
        let mut mods: Vec<&str> = vec![];
        if style.add_modifier.contains(Modifier::BOLD) {
            mods.push("1");
        }
        if style.add_modifier.contains(Modifier::DIM) {
            mods.push("2");
        }
        if style.add_modifier.contains(Modifier::ITALIC) {
            mods.push("3");
        }
        if style.add_modifier.contains(Modifier::UNDERLINED) {
            mods.push("4");
        }
        if style.add_modifier.contains(Modifier::SLOW_BLINK) {
            mods.push("5");
        }
        if style.add_modifier.contains(Modifier::RAPID_BLINK) {
            mods.push("6");
        }
        if style.add_modifier.contains(Modifier::CROSSED_OUT) {
            mods.push("9");
        }
        if mods.is_empty() {
            return content;
        }
        return format!("\x1b[{}m{}\x1b[0m", mods.join(";"), content);
    }
    format!("\x1b[{}m{}\x1b[0m", codes.join(";"), content)
}

pub fn line_to_ansi(line: &[Span]) -> String {
    line.iter().map(span_to_ansi).collect()
}
